INSERT INTO anitrack.anime (anime_id, title, title_english, title_japanese, image_url, type_id, source, episodes, status, aired_from, aired_to, duration_min, rating_id, score, scored_by, score_rank, popularity, members, favorites, background, premiered_season, premiered_year, broadcast) VALUES (1, 'Cowboy Bebop', 'Cowboy Bebop', 'カウボーイビバップ', 'https://cdn.myanimelist.net/images/anime/4/19644.jpg', 1, 'Original', 26, 'Finished Airing', '1998-04-03', '1999-04-24', 24, 4, 8.81, 365465, 27, 38, 707773, 39145, 'When Cowboy Bebop first aired in spring of 1998 on TV Tokyo, only episodes 2, 3, 7-15, and 18 were broadcast, it was concluded with a recap special known as Yose Atsume Blues. This was due to anime censorship having increased following the big controversies over Evangelion, as a result most of the series was pulled from the air due to violent content. Satellite channel WOWOW picked up the series in the fall of that year and aired it in its entirety uncensored. Cowboy Bebop was not a ratings hit in Japan, but sold over 19,000 DVD units in the initial release run, and 81,000 overall. Protagonist Spike Spiegel won Best Male Character, and Megumi Hayashibara won Best Voice Actor for her role as Faye Valentine in the 1999 and 2000 Anime Grand Prix, respectively.Cowboy Bebop''s biggest influence has been in the United States, where it premiered on Adult Swim in 2001 with many reruns since. The show''s heavy Western influence struck a chord with American viewers, where it became a "gateway drug" to anime aimed at adult audiences.', 'Spring', 1998, 'Saturdays at 01:00 (JST)') ON CONFLICT (anime_id) DO UPDATE SET title = EXCLUDED.title, title_english = COALESCE(EXCLUDED.title_english, anitrack.anime.title_english), title_japanese = COALESCE(EXCLUDED.title_japanese, anitrack.anime.title_japanese), image_url = COALESCE(EXCLUDED.image_url, anitrack.anime.image_url), type_id = EXCLUDED.type_id, source = COALESCE(EXCLUDED.source, anitrack.anime.source), episodes = EXCLUDED.episodes, status = EXCLUDED.status, aired_from = COALESCE(EXCLUDED.aired_from, anitrack.anime.aired_from), aired_to = COALESCE(EXCLUDED.aired_to, anitrack.anime.aired_to), duration_min = COALESCE(EXCLUDED.duration_min, anitrack.anime.duration_min), rating_id = COALESCE(EXCLUDED.rating_id, anitrack.anime.rating_id), score = EXCLUDED.score, scored_by = EXCLUDED.scored_by, score_rank = COALESCE(EXCLUDED.score_rank, anitrack.anime.score_rank), popularity = COALESCE(EXCLUDED.popularity, anitrack.anime.popularity), members = GREATEST(EXCLUDED.members, anitrack.anime.members), favorites = GREATEST(EXCLUDED.favorites, anitrack.anime.favorites), background = COALESCE(EXCLUDED.background, anitrack.anime.background), premiered_season = COALESCE(EXCLUDED.premiered_season, anitrack.anime.premiered_season), premiered_year = COALESCE(EXCLUDED.premiered_year, anitrack.anime.premiered_year), broadcast = COALESCE(EXCLUDED.broadcast, anitrack.anime.broadcast);
INSERT INTO anitrack.anime (anime_id, title, title_english, title_japanese, image_url, type_id, source, episodes, status, aired_from, aired_to, duration_min, rating_id, score, scored_by, score_rank, popularity, members, favorites, background, premiered_season, premiered_year, broadcast) VALUES (6, 'Trigun', 'Trigun', 'トライガン', 'https://cdn.myanimelist.net/images/anime/7/20310.jpg', 1, 'Manga', 26, 'Finished Airing', '1998-04-01', '1998-09-30', 24, 3, 8.31, 197843, 234, 138, 373877, 9795, 'The Japanese release by Victor Entertainment has different openings relating to the specific episode it''s played on. The initial Geneon Entertainment USA (then known as Pioneer) releases on VHS and DVD (singles, Signature Series, and box set) used only the first opening on each episode. This was due to the Japanese licensor providing them clean materials for only the first opening to put the English credits on. Geneon later fixed this mistake on their Limited Edition tin releases in 2005/2006, as well as on the Remix singles. Following Geneon USA''s demise in late 2007, the show went out of print. When FUNimation Entertainment picked up the show in 2010 and released it, they repeated Geneon''s mistake of using only the first opening on every episode. This mistake was later fixed in 2013 on the Anime Classics re-release.', 'Spring', 1998, 'Thursdays at 01:15 (JST)') ON CONFLICT (anime_id) DO UPDATE SET title = EXCLUDED.title, title_english = COALESCE(EXCLUDED.title_english, anitrack.anime.title_english), title_japanese = COALESCE(EXCLUDED.title_japanese, anitrack.anime.title_japanese), image_url = COALESCE(EXCLUDED.image_url, anitrack.anime.image_url), type_id = EXCLUDED.type_id, source = COALESCE(EXCLUDED.source, anitrack.anime.source), episodes = EXCLUDED.episodes, status = EXCLUDED.status, aired_from = COALESCE(EXCLUDED.aired_from, anitrack.anime.aired_from), aired_to = COALESCE(EXCLUDED.aired_to, anitrack.anime.aired_to), duration_min = COALESCE(EXCLUDED.duration_min, anitrack.anime.duration_min), rating_id = COALESCE(EXCLUDED.rating_id, anitrack.anime.rating_id), score = EXCLUDED.score, scored_by = EXCLUDED.scored_by, score_rank = COALESCE(EXCLUDED.score_rank, anitrack.anime.score_rank), popularity = COALESCE(EXCLUDED.popularity, anitrack.anime.popularity), members = GREATEST(EXCLUDED.members, anitrack.anime.members), favorites = GREATEST(EXCLUDED.favorites, anitrack.anime.favorites), background = COALESCE(EXCLUDED.background, anitrack.anime.background), premiered_season = COALESCE(EXCLUDED.premiered_season, anitrack.anime.premiered_season), premiered_year = COALESCE(EXCLUDED.premiered_year, anitrack.anime.premiered_year), broadcast = COALESCE(EXCLUDED.broadcast, anitrack.anime.broadcast);
