INSERT INTO anitrack.anime (anime_id, title, title_english, title_japanese, image_url, type_id, source, episodes, status, aired_from, aired_to, duration_min, rating_id, score, scored_by, score_rank, popularity, members, favorites, background, premiered_season, premiered_year, broadcast) VALUES (30, 'Neon Genesis Evangelion', 'Neon Genesis Evangelion', '新世紀エヴァンゲリオン', 'https://cdn.myanimelist.net/images/anime/12/21418.jpg', 1, 'Original', 26, 'Finished Airing', '1995-10-04', '1996-03-27', 24, 3, 8.32, 364012, 223, 48, 641101, 41098, 'Director Hideaki Anno''s depression is what led to the dark themes of Neon Genesis Evangelion. Budgetary problems and parental complaints about content led to the original ending being scrapped and replaced with an extremely limited-animation ending breaking from the main plot. A movie, End of Evangelion, was later made based in part on the original planned ending and in part on Anno''s increasing frustration with the otaku fanbase. The series'' mix of psychoanalysis, religious symbolism, and genre deconstruction proved extremely influential on mature anime in the late ''90s onward. The Japan Media Arts Festival in 2006 ranked it as the most popular anime of all time.', 'Fall', 1995, 'Wednesdays at 18:30 (JST)') ON CONFLICT (anime_id) DO UPDATE SET title = EXCLUDED.title, title_english = COALESCE(EXCLUDED.title_english, anitrack.anime.title_english), title_japanese = COALESCE(EXCLUDED.title_japanese, anitrack.anime.title_japanese), image_url = COALESCE(EXCLUDED.image_url, anitrack.anime.image_url), type_id = EXCLUDED.type_id, source = COALESCE(EXCLUDED.source, anitrack.anime.source), episodes = EXCLUDED.episodes, status = EXCLUDED.status, aired_from = COALESCE(EXCLUDED.aired_from, anitrack.anime.aired_from), aired_to = COALESCE(EXCLUDED.aired_to, anitrack.anime.aired_to), duration_min = COALESCE(EXCLUDED.duration_min, anitrack.anime.duration_min), rating_id = COALESCE(EXCLUDED.rating_id, anitrack.anime.rating_id), score = EXCLUDED.score, scored_by = EXCLUDED.scored_by, score_rank = COALESCE(EXCLUDED.score_rank, anitrack.anime.score_rank), popularity = COALESCE(EXCLUDED.popularity, anitrack.anime.popularity), members = GREATEST(EXCLUDED.members, anitrack.anime.members), favorites = GREATEST(EXCLUDED.favorites, anitrack.anime.favorites), background = COALESCE(EXCLUDED.background, anitrack.anime.background), premiered_season = COALESCE(EXCLUDED.premiered_season, anitrack.anime.premiered_season), premiered_year = COALESCE(EXCLUDED.premiered_year, anitrack.anime.premiered_year), broadcast = COALESCE(EXCLUDED.broadcast, anitrack.anime.broadcast);
INSERT INTO anitrack.anime (anime_id, title, title_english, title_japanese, image_url, type_id, source, episodes, status, aired_from, aired_to, duration_min, rating_id, score, scored_by, score_rank, popularity, members, favorites, background, premiered_season, premiered_year, broadcast) VALUES (32, 'Neon Genesis Evangelion: The End of Evangelion', 'Neon Genesis Evangelion: The End of Evangelion', '新世紀エヴァンゲリオン劇場版 THE END OF EVANGELION', 'https://cdn.myanimelist.net/images/anime/12/39305.jpg', 2, 'Original', 1, 'Finished Airing', '1997-07-19', '1997-07-19', 87, 5, 8.48, 193744, 113, 216, 295923, 8159, 'Shinseiki Evangelion Gekijouban: The End of Evangelion is an alternate version of the series ending, which either supplements or replaces episodes 25 and 26, depending on how they are viewed.The movie was awarded the Animage Anime Grand Prix prize for 1997, the Japan Academy Prize for Biggest Public Sensation of the Year, and Special Audience Choice Award by the 1997 Animation Kobe.', 'Summer', 1997, NULL) ON CONFLICT (anime_id) DO UPDATE SET title = EXCLUDED.title, title_english = COALESCE(EXCLUDED.title_english, anitrack.anime.title_english), title_japanese = COALESCE(EXCLUDED.title_japanese, anitrack.anime.title_japanese), image_url = COALESCE(EXCLUDED.image_url, anitrack.anime.image_url), type_id = EXCLUDED.type_id, source = COALESCE(EXCLUDED.source, anitrack.anime.source), episodes = EXCLUDED.episodes, status = EXCLUDED.status, aired_from = COALESCE(EXCLUDED.aired_from, anitrack.anime.aired_from), aired_to = COALESCE(EXCLUDED.aired_to, anitrack.anime.aired_to), duration_min = COALESCE(EXCLUDED.duration_min, anitrack.anime.duration_min), rating_id = COALESCE(EXCLUDED.rating_id, anitrack.anime.rating_id), score = EXCLUDED.score, scored_by = EXCLUDED.scored_by, score_rank = COALESCE(EXCLUDED.score_rank, anitrack.anime.score_rank), popularity = COALESCE(EXCLUDED.popularity, anitrack.anime.popularity), members = GREATEST(EXCLUDED.members, anitrack.anime.members), favorites = GREATEST(EXCLUDED.favorites, anitrack.anime.favorites), background = COALESCE(EXCLUDED.background, anitrack.anime.background), premiered_season = COALESCE(EXCLUDED.premiered_season, anitrack.anime.premiered_season), premiered_year = COALESCE(EXCLUDED.premiered_year, anitrack.anime.premiered_year), broadcast = COALESCE(EXCLUDED.broadcast, anitrack.anime.broadcast);
INSERT INTO anitrack.anime (anime_id, title, title_english, title_japanese, image_url, type_id, source, episodes, status, aired_from, aired_to, duration_min, rating_id, score, scored_by, score_rank, popularity, members, favorites, background, premiered_season, premiered_year, broadcast) VALUES (33, 'Kenpuu Denki Berserk', 'Berserk', '剣風伝奇ベルセルク', 'https://cdn.myanimelist.net/images/anime/12/18520.jpg', 1, 'Manga', 25, 'Finished Airing', '1997-10-08', '1998-04-01', 25, 5, 8.45, 153890, 132, 210, 302027, 12562, 'Kenpuu Denki Berserk is the first anime adaptation of the long-running, ongoing seinen manga series published in the bi-weekly magazine Young Animal created by Kentaro Miura in 1989. While the story in the anime is fairly loyal to the source material, heavy modifications were made to exclude some of the more graphic depictions of violence, as well as characters and other content that could not be covered within the length of the anime’s running time. These changes were approved by the series creator himself.', 'Fall', 1997, 'Wednesdays at 01:45 (JST)') ON CONFLICT (anime_id) DO UPDATE SET title = EXCLUDED.title, title_english = COALESCE(EXCLUDED.title_english, anitrack.anime.title_english), title_japanese = COALESCE(EXCLUDED.title_japanese, anitrack.anime.title_japanese), image_url = COALESCE(EXCLUDED.image_url, anitrack.anime.image_url), type_id = EXCLUDED.type_id, source = COALESCE(EXCLUDED.source, anitrack.anime.source), episodes = EXCLUDED.episodes, status = EXCLUDED.status, aired_from = COALESCE(EXCLUDED.aired_from, anitrack.anime.aired_from), aired_to = COALESCE(EXCLUDED.aired_to, anitrack.anime.aired_to), duration_min = COALESCE(EXCLUDED.duration_min, anitrack.anime.duration_min), rating_id = COALESCE(EXCLUDED.rating_id, anitrack.anime.rating_id), score = EXCLUDED.score, scored_by = EXCLUDED.scored_by, score_rank = COALESCE(EXCLUDED.score_rank, anitrack.anime.score_rank), popularity = COALESCE(EXCLUDED.popularity, anitrack.anime.popularity), members = GREATEST(EXCLUDED.members, anitrack.anime.members), favorites = GREATEST(EXCLUDED.favorites, anitrack.anime.favorites), background = COALESCE(EXCLUDED.background, anitrack.anime.background), premiered_season = COALESCE(EXCLUDED.premiered_season, anitrack.anime.premiered_season), premiered_year = COALESCE(EXCLUDED.premiered_year, anitrack.anime.premiered_year), broadcast = COALESCE(EXCLUDED.broadcast, anitrack.anime.broadcast);
INSERT INTO anitrack.anime (anime_id, title, title_english, title_japanese, image_url, type_id, source, episodes, status, aired_from, aired_to, duration_min, rating_id, score, scored_by, score_rank, popularity, members, favorites, background, premiered_season, premiered_year, broadcast) VALUES (43, 'Ghost in the Shell', 'Ghost in the Shell', 'GHOST IN THE SHELL（攻殻機動隊）', 'https://cdn.myanimelist.net/images/anime/10/82594.jpg', 2, 'Manga', 1, 'Finished Airing', '1995-11-18', '1995-11-18', 82, 5, 8.35, 182809, 192, 174, 329663, 7755, 'Mamoru Oshii''s Ghost in the Shell was the first film to adapt Masumane Shirow''s manga of the same name. It heavily condenses the original storyline, reducing the original material''s comic relief and sexual content in favor of a more serious tone and changing the setting from Japan to a city modelled after Hong Kong. The artwork within the animated film was produced using an innovative mix of cel animation and digital effects. Ghost in the Shell is one of the world''s most famous Japanese animated films, being the first to reach #1 on Billboard magazine''s video best-seller list, and also served as a major inspiration for the Wachowskis in their creation of the Matrix movies. A special edition titled Ghost in the Shell: 2.0 was released in 2008, which features scenes reanimated with additional CGI to match the style of the 2004''s sequel, Ghost in the Shell: Innocence.', 'Fall', 1995, NULL) ON CONFLICT (anime_id) DO UPDATE SET title = EXCLUDED.title, title_english = COALESCE(EXCLUDED.title_english, anitrack.anime.title_english), title_japanese = COALESCE(EXCLUDED.title_japanese, anitrack.anime.title_japanese), image_url = COALESCE(EXCLUDED.image_url, anitrack.anime.image_url), type_id = EXCLUDED.type_id, source = COALESCE(EXCLUDED.source, anitrack.anime.source), episodes = EXCLUDED.episodes, status = EXCLUDED.status, aired_from = COALESCE(EXCLUDED.aired_from, anitrack.anime.aired_from), aired_to = COALESCE(EXCLUDED.aired_to, anitrack.anime.aired_to), duration_min = COALESCE(EXCLUDED.duration_min, anitrack.anime.duration_min), rating_id = COALESCE(EXCLUDED.rating_id, anitrack.anime.rating_id), score = EXCLUDED.score, scored_by = EXCLUDED.scored_by, score_rank = COALESCE(EXCLUDED.score_rank, anitrack.anime.score_rank), popularity = COALESCE(EXCLUDED.popularity, anitrack.anime.popularity), members = GREATEST(EXCLUDED.members, anitrack.anime.members), favorites = GREATEST(EXCLUDED.favorites, anitrack.anime.favorites), background = COALESCE(EXCLUDED.background, anitrack.anime.background), premiered_season = COALESCE(EXCLUDED.premiered_season, anitrack.anime.premiered_season), premiered_year = COALESCE(EXCLUDED.premiered_year, anitrack.anime.premiered_year), broadcast = COALESCE(EXCLUDED.broadcast, anitrack.anime.broadcast);
