INSERT INTO anitrack.anime (anime_id, title, title_english, title_japanese, image_url, type_id, source, episodes, status, aired_from, aired_to, duration_min, rating_id, score, scored_by, score_rank, popularity, members, favorites, background, premiered_season, premiered_year, broadcast) VALUES (226, 'Elfen Lied', 'Elfen Lied', 'エルフェンリート', 'https://cdn.myanimelist.net/images/anime/10/6883.jpg', 1, 'Manga', 13, 'Finished Airing', '2004-07-25', '2004-10-17', 25, 5, 7.75, 514656, 982, 16, 833388, 20137, 'Elfen Lied is based on Lynn Okamoto''s seinen manga series of the same name and premiered while the manga was still in publication. The anime follows the source material through the first 7 volumes, with several alterations to the story, and concludes with an exclusive ending. In an interview, director Mamoru Kanbe expressed his disappointment in having to ''condense'' to story into 13 episodes and felt that more were needed to include significant plot details that would have made the series more emotive.The artistic design of both the opening and ending sequences are heavily inspired by the works of Austrian symbolist painter Gustav Klimt. Colors and patterns resembling Klimt''s distinct style were used and characters of the series were drawn to recreate several paintings from the artist’s golden period, including The Kiss (Lovers). The opening theme Lilium, which is sung in Ecclesiastical Latin, uses lyrics taken from The Bible, the Renaissance hymn Ave mundi spes Maria, as well as the alchemical compendium Theatrum Chemicum.', 'Summer', 2004, 'Sundays at 22:30 (JST)') ON CONFLICT (anime_id) DO UPDATE SET title = EXCLUDED.title, title_english = COALESCE(EXCLUDED.title_english, anitrack.anime.title_english), title_japanese = COALESCE(EXCLUDED.title_japanese, anitrack.anime.title_japanese), image_url = COALESCE(EXCLUDED.image_url, anitrack.anime.image_url), type_id = EXCLUDED.type_id, source = COALESCE(EXCLUDED.source, anitrack.anime.source), episodes = EXCLUDED.episodes, status = EXCLUDED.status, aired_from = COALESCE(EXCLUDED.aired_from, anitrack.anime.aired_from), aired_to = COALESCE(EXCLUDED.aired_to, anitrack.anime.aired_to), duration_min = COALESCE(EXCLUDED.duration_min, anitrack.anime.duration_min), rating_id = COALESCE(EXCLUDED.rating_id, anitrack.anime.rating_id), score = EXCLUDED.score, scored_by = EXCLUDED.scored_by, score_rank = COALESCE(EXCLUDED.score_rank, anitrack.anime.score_rank), popularity = COALESCE(EXCLUDED.popularity, anitrack.anime.popularity), members = GREATEST(EXCLUDED.members, anitrack.anime.members), favorites = GREATEST(EXCLUDED.favorites, anitrack.anime.favorites), background = COALESCE(EXCLUDED.background, anitrack.anime.background), premiered_season = COALESCE(EXCLUDED.premiered_season, anitrack.anime.premiered_season), premiered_year = COALESCE(EXCLUDED.premiered_year, anitrack.anime.premiered_year), broadcast = COALESCE(EXCLUDED.broadcast, anitrack.anime.broadcast);
