INSERT INTO anitrack.anime (anime_id, title, title_english, title_japanese, image_url, type_id, source, episodes, status, aired_from, aired_to, duration_min, rating_id, score, scored_by, score_rank, popularity, members, favorites, background, premiered_season, premiered_year, broadcast) VALUES (813, 'Dragon Ball Z', 'Dragon Ball Z', 'ドラゴンボールZ', 'https://cdn.myanimelist.net/images/anime/6/20936.jpg', 1, 'Manga', 291, 'Finished Airing', '1989-04-26', '1996-01-31', 24, 3, 8.31, 367982, 228, 70, 534974, 21295, 'The U.S. version is a dubbed alternative version of the Original Japanese anime. For example, blood has been taken out, beer is called root-beer, dead is called "Another Universe" and people emigrate before the destroying of cities. (Source: YouTube movie - Anime History Day)The U.S. version edited and compiled the original for a reduced episode count of 276, instead of the original 291. The proper episode count was later restored on the uncut "Orange Brick" Season Set releases by FUNimation Entertainment released from 2006 to 2009. Additionally, the North American "Orange Brick" Season Sets as well as the Season Set Blu-rays crop the show from its original 4:3 aspect ratio to 16:9. The only complete 4:3 release ever released in English were the Dragon Boxes which have long since gone out of print.', 'Spring', 1989, 'Wednesdays at 19:00 (JST)') ON CONFLICT (anime_id) DO UPDATE SET title = EXCLUDED.title, title_english = COALESCE(EXCLUDED.title_english, anitrack.anime.title_english), title_japanese = COALESCE(EXCLUDED.title_japanese, anitrack.anime.title_japanese), image_url = COALESCE(EXCLUDED.image_url, anitrack.anime.image_url), type_id = EXCLUDED.type_id, source = COALESCE(EXCLUDED.source, anitrack.anime.source), episodes = EXCLUDED.episodes, status = EXCLUDED.status, aired_from = COALESCE(EXCLUDED.aired_from, anitrack.anime.aired_from), aired_to = COALESCE(EXCLUDED.aired_to, anitrack.anime.aired_to), duration_min = COALESCE(EXCLUDED.duration_min, anitrack.anime.duration_min), rating_id = COALESCE(EXCLUDED.rating_id, anitrack.anime.rating_id), score = EXCLUDED.score, scored_by = EXCLUDED.scored_by, score_rank = COALESCE(EXCLUDED.score_rank, anitrack.anime.score_rank), popularity = COALESCE(EXCLUDED.popularity, anitrack.anime.popularity), members = GREATEST(EXCLUDED.members, anitrack.anime.members), favorites = GREATEST(EXCLUDED.favorites, anitrack.anime.favorites), background = COALESCE(EXCLUDED.background, anitrack.anime.background), premiered_season = COALESCE(EXCLUDED.premiered_season, anitrack.anime.premiered_season), premiered_year = COALESCE(EXCLUDED.premiered_year, anitrack.anime.premiered_year), broadcast = COALESCE(EXCLUDED.broadcast, anitrack.anime.broadcast);
