INSERT INTO anitrack.anime (anime_id, title, title_english, title_japanese, image_url, type_id, source, episodes, status, aired_from, aired_to, duration_min, rating_id, score, scored_by, score_rank, popularity, members, favorites, background, premiered_season, premiered_year, broadcast) VALUES (1575, 'Code Geass: Hangyaku no Lelouch', 'Code Geass: Lelouch of the Rebellion', 'コードギアス 反逆のルルーシュ', 'https://cdn.myanimelist.net/images/anime/5/50331.jpg', 1, 'Original', 25, 'Finished Airing', '2006-10-06', '2007-07-29', 24, 4, 8.79, 627740, 30, 9, 986897, 63614, 'Code Geass: Hangyaku no Lelouch is an original anime series by Sunrise animation studio with original character designs by the all-female Japanese manga artist group Clamp. Manga and light novels based off the show have been published by Kadokawa Shoten. The show has sold millions of DVDs and Blu-ray volumes and is extremely popular in both Japan and North America. The show is known for its multi-genre appeal and for its diverse cast of characters who face many moral dilemmas over the course of the series.The last two episodes received a pre-airing on an event, July 21, 2007. Regular broadcasting was on July 29, 2007.The series won: "The Best Anime TV Series" award at the 2007 Tokyo International Anime Fair, "The Best TV animation" award at the twelfth Animation Kobe, and "The Most Popular Anime" award at the Animage ''s 29th Annual Anime Grand Prix.', 'Fall', 2006, 'Fridays at 01:25 (JST)') ON CONFLICT (anime_id) DO UPDATE SET title = EXCLUDED.title, title_english = COALESCE(EXCLUDED.title_english, anitrack.anime.title_english), title_japanese = COALESCE(EXCLUDED.title_japanese, anitrack.anime.title_japanese), image_url = COALESCE(EXCLUDED.image_url, anitrack.anime.image_url), type_id = EXCLUDED.type_id, source = COALESCE(EXCLUDED.source, anitrack.anime.source), episodes = EXCLUDED.episodes, status = EXCLUDED.status, aired_from = COALESCE(EXCLUDED.aired_from, anitrack.anime.aired_from), aired_to = COALESCE(EXCLUDED.aired_to, anitrack.anime.aired_to), duration_min = COALESCE(EXCLUDED.duration_min, anitrack.anime.duration_min), rating_id = COALESCE(EXCLUDED.rating_id, anitrack.anime.rating_id), score = EXCLUDED.score, scored_by = EXCLUDED.scored_by, score_rank = COALESCE(EXCLUDED.score_rank, anitrack.anime.score_rank), popularity = COALESCE(EXCLUDED.popularity, anitrack.anime.popularity), members = GREATEST(EXCLUDED.members, anitrack.anime.members), favorites = GREATEST(EXCLUDED.favorites, anitrack.anime.favorites), background = COALESCE(EXCLUDED.background, anitrack.anime.background), premiered_season = COALESCE(EXCLUDED.premiered_season, anitrack.anime.premiered_season), premiered_year = COALESCE(EXCLUDED.premiered_year, anitrack.anime.premiered_year), broadcast = COALESCE(EXCLUDED.broadcast, anitrack.anime.broadcast);
