INSERT INTO anitrack.anime (anime_id, title, title_english, title_japanese, image_url, type_id, source, episodes, status, aired_from, aired_to, duration_min, rating_id, score, scored_by, score_rank, popularity, members, favorites, background, premiered_season, premiered_year, broadcast) VALUES (9756, 'Mahou Shoujo Madoka★Magica', 'Puella Magi Madoka Magica', '魔法少女まどか★マギカ', 'https://cdn.myanimelist.net/images/anime/11/55225.jpg', 1, 'Original', 12, 'Finished Airing', '2011-01-07', '2011-04-22', 24, 3, 8.46, 380424, 125, 50, 635296, 34352, 'Mahou Shoujo Madoka★Magica has received widespread critical acclaim, with critics praising the writing, visuals and soundtrack of the series, as well as its approach to the magical girl subgenre. It has also been a commercial success, with each BD volume selling more than 50,000 copies.The series won several awards in Japan, such as the Television Award at the 16th Animation Kobe Awards, as well as 12 Newtype Anime Awards and the Grand Prize for animation in the 2011 Japan Media Arts awards. In 2015, the show was also awarded the inaugural Sugoi Japan Grand Prix, Japan''s nationwide vote for manga, anime, and novels considered as cultural assets that have the potential to be beloved all over the world, among all the works published since 2005.', 'Winter', 2011, 'Fridays at 01:25 (JST)') ON CONFLICT (anime_id) DO UPDATE SET title = EXCLUDED.title, title_english = COALESCE(EXCLUDED.title_english, anitrack.anime.title_english), title_japanese = COALESCE(EXCLUDED.title_japanese, anitrack.anime.title_japanese), image_url = COALESCE(EXCLUDED.image_url, anitrack.anime.image_url), type_id = EXCLUDED.type_id, source = COALESCE(EXCLUDED.source, anitrack.anime.source), episodes = EXCLUDED.episodes, status = EXCLUDED.status, aired_from = COALESCE(EXCLUDED.aired_from, anitrack.anime.aired_from), aired_to = COALESCE(EXCLUDED.aired_to, anitrack.anime.aired_to), duration_min = COALESCE(EXCLUDED.duration_min, anitrack.anime.duration_min), rating_id = COALESCE(EXCLUDED.rating_id, anitrack.anime.rating_id), score = EXCLUDED.score, scored_by = EXCLUDED.scored_by, score_rank = COALESCE(EXCLUDED.score_rank, anitrack.anime.score_rank), popularity = COALESCE(EXCLUDED.popularity, anitrack.anime.popularity), members = GREATEST(EXCLUDED.members, anitrack.anime.members), favorites = GREATEST(EXCLUDED.favorites, anitrack.anime.favorites), background = COALESCE(EXCLUDED.background, anitrack.anime.background), premiered_season = COALESCE(EXCLUDED.premiered_season, anitrack.anime.premiered_season), premiered_year = COALESCE(EXCLUDED.premiered_year, anitrack.anime.premiered_year), broadcast = COALESCE(EXCLUDED.broadcast, anitrack.anime.broadcast);
