INSERT INTO anitrack.anime (anime_id, title, title_english, title_japanese, image_url, type_id, source, episodes, status, aired_from, aired_to, duration_min, rating_id, score, scored_by, score_rank, popularity, members, favorites, background, premiered_season, premiered_year, broadcast) VALUES (9989, 'Ano Hi Mita Hana no Namae wo Bokutachi wa Mada Shiranai.', 'anohana: The Flower We Saw That Day', 'あの日見た花の名前を僕達はまだ知らない。', 'https://cdn.myanimelist.net/images/anime/5/79697.jpg', 1, 'Original', 11, 'Finished Airing', '2011-04-15', '2011-06-24', 22, 3, 8.55, 397955, 81, 45, 661053, 21155, 'Ano Hi Mita Hana no Namae wo Bokutachi wa Mada Shiranai. reunites the lead production staff of the 2008 anime series Toradora! It was first teased in December 2010 as a joint production of Aniplex, Fuji Television, and animation studio A-1 Pictures under the title AnoHana Project. The series is set in the city of Chichibu, Saitama Prefecture.The first Blu-ray volume, which went on sale on June 29, 2011, sold more than 31,000 copies in the first week of release. At the time, that first week sales figure was the third highest for a first volume Blu-ray release of a television anime, after Mahou Shoujo Madoka★Magica (2011) and K-On! (2009). AnoHana received a Jury Selection award in the Animation division of the 15th Japan Media Arts Festival.A visual novel adaptation for the PlayStation Portable, which diverges from the story of the anime and contains an original ending, was developed by Guyzware and published by 5pb. on August 30, 2012. AnoHana was also adapted into a special live-action television drama, which aired on Fuji Television on September 21, 2015.', 'Spring', 2011, 'Fridays at 01:15 (JST)') ON CONFLICT (anime_id) DO UPDATE SET title = EXCLUDED.title, title_english = COALESCE(EXCLUDED.title_english, anitrack.anime.title_english), title_japanese = COALESCE(EXCLUDED.title_japanese, anitrack.anime.title_japanese), image_url = COALESCE(EXCLUDED.image_url, anitrack.anime.image_url), type_id = EXCLUDED.type_id, source = COALESCE(EXCLUDED.source, anitrack.anime.source), episodes = EXCLUDED.episodes, status = EXCLUDED.status, aired_from = COALESCE(EXCLUDED.aired_from, anitrack.anime.aired_from), aired_to = COALESCE(EXCLUDED.aired_to, anitrack.anime.aired_to), duration_min = COALESCE(EXCLUDED.duration_min, anitrack.anime.duration_min), rating_id = COALESCE(EXCLUDED.rating_id, anitrack.anime.rating_id), score = EXCLUDED.score, scored_by = EXCLUDED.scored_by, score_rank = COALESCE(EXCLUDED.score_rank, anitrack.anime.score_rank), popularity = COALESCE(EXCLUDED.popularity, anitrack.anime.popularity), members = GREATEST(EXCLUDED.members, anitrack.anime.members), favorites = GREATEST(EXCLUDED.favorites, anitrack.anime.favorites), background = COALESCE(EXCLUDED.background, anitrack.anime.background), premiered_season = COALESCE(EXCLUDED.premiered_season, anitrack.anime.premiered_season), premiered_year = COALESCE(EXCLUDED.premiered_year, anitrack.anime.premiered_year), broadcast = COALESCE(EXCLUDED.broadcast, anitrack.anime.broadcast);
