-- ============================================================================
-- AniCine v2.0 — Sinkronisasi 383 Anime dari Dataset Soundtrack CSV
-- Tujuan   : Menambahkan seluruh 383 judul anime dari all_soundtracks_flat.csv
--            (lengkap dengan metadata anime, genre, studio/company, sinonim,
--            dan lagu tema OP/ED) ke database anitrack tanpa merusak data
--            user, watchlist, booking, dan anime_cinema_map yang sudah ada.
--
-- Jalankan di VM Azure / lokal sebagai superuser postgres:
--   sudo -u postgres psql -d db_anitrack < database/sync_csv_anime_to_anitrack.sql
-- ============================================================================

\set ON_ERROR_STOP on

BEGIN;
SET LOCAL search_path = anitrack, public;

ALTER TABLE anitrack.anime DISABLE TRIGGER trg_audit_anime;

-- 1. Upsert master studio/produser (company)
SELECT setval('anitrack.company_company_id_seq', COALESCE((SELECT MAX(company_id) FROM anitrack.company), 1), true);

-- 2. Upsert katalog anime (393 judul total termasuk 383 anime CSV)

-- 3. Upsert relasi genre (anime_genre)

-- 4. Upsert relasi studio & produser (anime_company via nama company)

-- 5. Upsert judul sinonim / alternatif CSV (anime_synonym)

-- 6. Upsert lagu tema OP/ED dari CSV (anime_theme)

-- 7. Sinkronkan ulang sequence PostgreSQL
SELECT setval('anitrack.anime_anime_id_seq', COALESCE((SELECT MAX(anime_id) FROM anitrack.anime), 1), true);
SELECT setval('anitrack.company_company_id_seq', COALESCE((SELECT MAX(company_id) FROM anitrack.company), 1), true);
SELECT setval('anitrack.anime_synonym_synonym_id_seq', COALESCE((SELECT MAX(synonym_id) FROM anitrack.anime_synonym), 1), true);
SELECT setval('anitrack.anime_theme_theme_id_seq', COALESCE((SELECT MAX(theme_id) FROM anitrack.anime_theme), 1), true);

ALTER TABLE anitrack.anime ENABLE TRIGGER trg_audit_anime;

COMMIT;

-- Verifikasi akhir
SELECT
    (SELECT COUNT(*) FROM anitrack.anime) AS total_anime,
    (SELECT COUNT(*) FROM anitrack.anime_genre) AS total_relasi_genre,
    (SELECT COUNT(*) FROM anitrack.anime_company) AS total_relasi_studio,
    (SELECT COUNT(*) FROM anitrack.anime_synonym) AS total_sinonim,
    (SELECT COUNT(*) FROM anitrack.anime_theme) AS total_lagu_tema;
